    }
    if (ctx->d_scores) {
        cudaFree(ctx->d_scores);
    }
    if (ctx->d_prob) {
        cudaFree(ctx->d_prob);
    }
    if (ctx->d_part_val) {
        cudaFree(ctx->d_part_val);
    }
    if (ctx->d_part_idx) {
        cudaFree(ctx->d_part_idx);
    }
    if (ctx->d_base) {
