SKIP = 5
METHODS = ("eager", "graph-nodes", "graph-stream")
NCU_CALL_TIMEOUT = 300.0
NCU_BUDGET = 900.0
NCU_MIN_CALL = 30.0
KERNEL_REGEX = "cr_reread"
INNER_TAG = "CR_L2_INNER "
