454	ggml_tensor * llm_build_delta_net_base::build_conv_state(
455	        llm_graph_input_rs * inp,
456	        ggml_tensor *        conv_states_all,
457	        ggml_tensor *        qkv_mixed,
458	        int64_t              conv_kernel_size,
459	        int64_t              conv_channels,
460	        int                  il) {
461	    const auto * mctx_cur = inp->mctx;
462	
463	    const auto kv_head  = mctx_cur->get_head();
464	    const auto mem_size = mctx_cur->get_size();
465	
466	    const int64_t n_seqs = ubatch.n_seqs;
467	
468	    ggml_tensor * conv_states = build_rs(inp, conv_states_all, hparams.n_embd_r(), n_seqs);
469	    cb(conv_states, "conv_states", il);
470	
471	    conv_states = ggml_reshape_3d(ctx0, conv_states, conv_kernel_size - 1, conv_channels, n_seqs);
472	    cb(conv_states, "conv_states_reshaped", il);
473	
474	    qkv_mixed = ggml_transpose(ctx0, qkv_mixed);
475	    cb(qkv_mixed, "qkv_mixed_transposed", il);
476	
477	    ggml_tensor * conv_input = ggml_concat(ctx0, conv_states, qkv_mixed, 0);
478	    cb(conv_input, "conv_input", il);
479	
480	    const int64_t row_count = (conv_kernel_size - 1) * conv_channels;
481	
482	    const size_t row_size  = ggml_row_size(conv_states_all->type, row_count);
483	
484	    if (cparams.n_rs_seq == 0) {
485	        const int64_t s_idx  = conv_input->ne[0] - conv_states->ne[0];
486	        const int64_t s_slot = 0;
487	
488	        ggml_tensor * conv_state_last =
489	            ggml_view_3d(ctx0, conv_input,
490	                    conv_kernel_size - 1, conv_channels, n_seqs,
491	                    conv_input->nb[1], conv_input->nb[2],
492	                    ggml_row_size(conv_input->type, s_idx));
493	        cb(conv_state_last, "conv_state_last", il);
494	
495	        ggml_tensor * conv_state_update =
496	            ggml_view_2d(ctx0, conv_states_all,
497	                    row_count, n_seqs, conv_states_all->nb[1],
498	                    (s_slot * mem_size + kv_head) * row_size);
499	        cb(conv_state_update, "conv_state_update", il);
500	
501	        ggml_build_forward_expand(gf, ggml_cpy(ctx0, conv_state_last, conv_state_update));
502	    } else {
503	        // [TAG_RECURRENT_ROLLBACK_SPLITS]
504	        // this logic assumes that the last (n_rs_seq + 1) tokens of a sequence in a batch are inside
505	        //   the same ubatch, which `split_equal()` guarantees via its n_keep_tail argument
506	
507	        const int64_t K = (int64_t) cparams.n_rs_seq + 1;
508	
509	        for (int64_t t = 1; t <= K; ++t) {
510	            const int64_t s_idx  = std::max<int64_t>(0, conv_input->ne[0] - conv_states->ne[0] - K + t);
511	            const int64_t s_slot = K - t;
512	
513	            ggml_tensor * conv_state_last =
514	                ggml_view_3d(ctx0, conv_input,
515	                        conv_kernel_size - 1, conv_channels, n_seqs,
516	                        conv_input->nb[1], conv_input->nb[2],
517	                        ggml_row_size(conv_input->type, s_idx));
518	
519	            ggml_tensor * conv_state_update =
520	                ggml_view_2d(ctx0,
521	                        conv_states_all, row_count, n_seqs,
522	                        conv_states_all->nb[1],
523	                        (s_slot * mem_size + kv_head) * row_size);
524	
525	            ggml_build_forward_expand(gf, ggml_cpy(ctx0, conv_state_last, conv_state_update));
526	        }
527	    }
528	
529	    return conv_input;
530	}
