532	ggml_tensor * llm_build_delta_net_base::build_recurrent_attn(
533	        llm_graph_input_rs * inp,
534	        ggml_tensor *        ssm_states_all,
535	        ggml_tensor *        q,
536	        ggml_tensor *        k,
537	        ggml_tensor *        v,
538	        ggml_tensor *        g,
539	        ggml_tensor *        b,
540	        ggml_tensor *        s,
541	        int                  il,
542	        ggml_tensor *        state_rows) {
543	    const auto * mctx_cur   = inp->mctx;
544	    const auto   kv_head    = mctx_cur->get_head();
545	    const uint32_t mem_size = mctx_cur->get_size();
546	
547	    // dims from v (always (S_v, H_v, T, B)): in rows mode `s` is the 2D cache
548	    // view, so its shape no longer carries them
549	    const int64_t S_v          = v->ne[0];
550	    const int64_t H_v          = v->ne[1];
551	    const int64_t n_seqs       = v->ne[3];
552	    const int64_t n_seq_tokens = q->ne[2];
553	
554	    const bool keep = cparams.n_rs_seq > 0;
555	
556	    GGML_ASSERT(state_rows == nullptr || keep); // rows mode is a ring-path optimization
557	
558	    if (!keep) {
559	        auto attn_out = build_delta_net(q, k, v, g, b, s, il);
560	        ggml_tensor * output    = attn_out.first;
561	        ggml_tensor * new_state = attn_out.second;
562	        cb(output, "attn_output", il);
563	        cb(new_state, "new_state", il);
564	
565	        ggml_build_forward_expand(gf,
566	                ggml_cpy(ctx0, new_state,
567	                    ggml_view_2d(ctx0, ssm_states_all, hparams.n_embd_s(), n_seqs, ssm_states_all->nb[1],
568	                        kv_head * hparams.n_embd_s() * ggml_element_size(ssm_states_all))));
569	
570	        return output;
571	    }
572	
573	    const int64_t D = S_v * S_v * H_v;
574	    const int64_t K = cparams.n_rs_seq + 1;
575	
