 15	
 16	std::pair<ggml_tensor *, ggml_tensor *> llm_build_delta_net_base::build_delta_net_chunking(
 17	        ggml_tensor * q,
 18	        ggml_tensor * k,
 19	        ggml_tensor * v,
 20	        ggml_tensor * g,
 21	        ggml_tensor * b,
 22	        ggml_tensor * s,
 23	        int           il) {
 24	    const int64_t S_k      = q->ne[0];
 25	    const int64_t H_k      = q->ne[1];
 26	    const int64_t n_tokens = q->ne[2];
 27	    const int64_t n_seqs   = q->ne[3];
 28	
 29	    const int64_t S_v = v->ne[0];
 30	    const int64_t H_v = v->ne[1];
 31	    const bool kda = (g->ne[0] == S_k && g->ne[1] == H_k);
 32	
 33	    GGML_ASSERT(S_k == S_v);
 34	    GGML_ASSERT(H_v % H_k == 0);
 35	
 36	    GGML_ASSERT(q->ne[0] == S_k && q->ne[1] == H_k && q->ne[2] == n_tokens && q->ne[3] == n_seqs);
 37	    GGML_ASSERT(k->ne[0] == S_k && k->ne[1] == H_k && k->ne[2] == n_tokens && k->ne[3] == n_seqs);
 38	    GGML_ASSERT(v->ne[0] == S_v && v->ne[1] == H_v && v->ne[2] == n_tokens && v->ne[3] == n_seqs);
 39	
 40	    GGML_ASSERT(g->ne[0] == 1   || g->ne[0] == S_v);
 41	    GGML_ASSERT(                   g->ne[1] == H_v && g->ne[2] == n_tokens && g->ne[3] == n_seqs);
 42	    GGML_ASSERT(b->ne[0] == 1   && b->ne[1] == H_v && b->ne[2] == n_tokens && b->ne[3] == n_seqs);
 43	    GGML_ASSERT(s->ne[0] == S_v && s->ne[1] == S_v && s->ne[2] == H_v      && s->ne[3] == n_seqs);
 44	
 45	    const float scale = 1.0f / sqrtf(S_k);
 46	
 47	    q = ggml_scale(ctx0, q, scale);
 48	
 49	    cb(q, "q_in", il);
 50	    cb(k, "k_in", il);
 51	    cb(v, "v_in", il);
 52	    cb(b, "b_in", il);
 53	    cb(g, "g_in", il);
 54	
 55	    q = ggml_permute(ctx0, q, 0, 2, 1, 3); // [S_k, n_tokens, H_k, n_seqs]
 56	    k = ggml_permute(ctx0, k, 0, 2, 1, 3); // [S_k, n_tokens, H_k, n_seqs]
 57	    v = ggml_permute(ctx0, v, 0, 2, 1, 3); // [S_v, n_tokens, H_v, n_seqs]
 58	    g = ggml_permute(ctx0, g, 0, 2, 1, 3); // [g_0, n_tokens, H_v, n_seqs]
 59	    b = ggml_permute(ctx0, b, 0, 2, 1, 3); // [  1, n_tokens, H_v, n_seqs]
 60	
 61	    const int CS = kda ? 16 : 64; // chunk size
 62	
 63	    const int pad = (CS - n_tokens % CS) % CS;
 64	    const int n_chunks = (n_tokens + pad) / CS;
 65	
 66	    q = ggml_pad(ctx0, q, 0, pad, 0, 0);
 67	    k = ggml_pad(ctx0, k, 0, pad, 0, 0);
 68	    v = ggml_pad(ctx0, v, 0, pad, 0, 0);
 69	    g = ggml_pad(ctx0, g, 0, pad, 0, 0);
 70	    b = ggml_pad(ctx0, b, 0, pad, 0, 0);
 71	
 72	    ggml_tensor * v_b = ggml_mul(ctx0, v, b);
 73	    ggml_tensor * k_b = ggml_mul(ctx0, k, b);
 74	
 75	    cb(v_b, "v_b", il);
 76	    cb(k_b, "k_b", il);
 77	
 78	    q   = ggml_reshape_4d(ctx0, q,   S_k, CS, n_chunks, H_k * n_seqs);
 79	    k   = ggml_reshape_4d(ctx0, k,   S_k, CS, n_chunks, H_k * n_seqs);
 80	    k_b = ggml_reshape_4d(ctx0, k_b, S_k, CS, n_chunks, H_v * n_seqs);
 81	    v   = ggml_reshape_4d(ctx0, v,   S_v, CS, n_chunks, H_v * n_seqs);
 82	    v_b = ggml_reshape_4d(ctx0, v_b, S_v, CS, n_chunks, H_v * n_seqs);
 83	
 84	    g = ggml_reshape_4d(ctx0, g, g->ne[0], CS, n_chunks, H_v * n_seqs);
 85	    b = ggml_reshape_4d(ctx0, b, 1,        CS, n_chunks, H_v * n_seqs);
 86	
 87	    // [CS, g_0, n_chunks, H_v * n_seqs]
 88	    // TODO: extend ggml_cumsum with axis parameter to avoid transpose
 89	    ggml_tensor * g_cs = ggml_cumsum(ctx0, ggml_cont(ctx0, ggml_transpose(ctx0, g)));
 90	    cb(g_cs, "g_cs", il);
 91	
 92	    ggml_tensor * kb = nullptr;
 93	    ggml_tensor * kq = nullptr;
 94	    if (kda) {
 95	        const int64_t CHB = n_chunks * H_k * n_seqs;
 96	
 97	        ggml_tensor * g_cs_i = ggml_reshape_4d(ctx0, g_cs, CS, 1, S_k, CHB);  // [chunk_size, 1, S_k, CHB]
 98	        ggml_tensor * g_cs_j = ggml_reshape_4d(ctx0, g_cs, 1, CS, S_k, CHB);  // [1, chunk_size, S_k, CHB]
 99	
100	        g_cs_j = ggml_repeat_4d(ctx0, g_cs_j, CS, CS, S_k, CHB);  // [1, chunk_size, S_k, CHB] -> [chunk_size, chunk_size, S_k, CHB]
101	
102	        // decay_mask [chunk_size,chunk_size,S_k,CHB]
103	        ggml_tensor * decay_mask;
104	        decay_mask = ggml_sub(ctx0, g_cs_j, g_cs_i);
105	        decay_mask = ggml_tri(ctx0, decay_mask, GGML_TRI_TYPE_LOWER_DIAG);
106	        decay_mask = ggml_exp(ctx0, decay_mask);
107	        cb(decay_mask, "decay_mask", il);
108	
109	        // decay_mask [S_k,BT_j,BT_i,CHB] *Note* second and third chunk_sizes are switched
110	        decay_mask = ggml_cont_4d(ctx0, ggml_permute(ctx0, decay_mask, 2, 1, 0, 3), S_k, CS, CS, CHB);
111	
112	        ggml_tensor * k_b_i = ggml_reshape_4d(ctx0, k_b, S_k, CS,  1, CHB);
113	        ggml_tensor * k_j   = ggml_reshape_4d(ctx0, k,   S_k,  1, CS, CHB);
114	        ggml_tensor * q_i   = ggml_reshape_4d(ctx0, q,   S_k, CS,  1, CHB);
115	
116	        ggml_tensor * decay_k_b_i = ggml_mul(ctx0, decay_mask, k_b_i);
117	        ggml_tensor * decay_q_i   = ggml_mul(ctx0, decay_mask, q_i);
118	
119	        // decay_k_b_i [S,BT,BT,CHB] @ k_j [S,1,BT,CHB] = Akk [BT,1,BT,CHB]
120	        kb = ggml_mul_mat(ctx0, decay_k_b_i, k_j);
121	        kq = ggml_mul_mat(ctx0, decay_q_i,   k_j);
122	
123	        kb = ggml_cont(ctx0, ggml_transpose(ctx0, ggml_reshape_4d(ctx0, kb, CS, CS, n_chunks, H_v * n_seqs)));
124	        kq = ggml_cont(ctx0, ggml_transpose(ctx0, ggml_reshape_4d(ctx0, kq, CS, CS, n_chunks, H_v * n_seqs)));
125	    } else {
126	        ggml_tensor * g_cs_i = g_cs;
127	        ggml_tensor * g_cs_j = ggml_reshape_4d(ctx0, g_cs, 1, CS, n_chunks, H_v * n_seqs);
128	
129	        g_cs_j = ggml_repeat_4d(ctx0, g_cs_j, CS, CS, n_chunks, H_v * n_seqs);
130	
131	        // [CS, CS, n_chunks, H_v * n_seqs]
132	        ggml_tensor * decay_mask;
133	        decay_mask = ggml_sub(ctx0, g_cs_j, g_cs_i);
134	        decay_mask = ggml_tri(ctx0, decay_mask, GGML_TRI_TYPE_LOWER_DIAG);
135	        decay_mask = ggml_exp(ctx0, decay_mask);
136	        cb(decay_mask, "decay_mask", il);
137	
138	        // [CS, CS, n_chunks, H_k * n_seqs]
139	        kb = ggml_mul_mat(ctx0, k,  k_b);
140	        kb = ggml_mul    (ctx0, kb, decay_mask);
141	
142	        // [CS, CS, n_chunks, H_k * n_seqs]
143	        kq = ggml_mul_mat(ctx0, k, q);
144	        kq = ggml_mul(ctx0, kq, decay_mask);
145	    }
146	
147	    kq = ggml_tri(ctx0, kq, GGML_TRI_TYPE_LOWER_DIAG);
148	    cb(kq, "kq", il);
149	
150	    // [CS, CS, n_chunks, H_k * n_seqs]
151	    ggml_tensor * attn;
152	    attn = ggml_tri(ctx0, kb, GGML_TRI_TYPE_LOWER);
153	    cb(attn, "attn", il);
154	
155	    ggml_tensor * identity;
156	    identity = ggml_view_1d(ctx0, attn, CS, 0);
157	    identity = ggml_fill   (ctx0, identity, 1.0f);
158	    identity = ggml_diag   (ctx0, identity);
159	
160	    ggml_tensor * lhs = ggml_add(ctx0, attn, identity);
161	    cb(lhs, "dnet_add_ch_lhs", il);
162	
163	    attn = ggml_neg(ctx0, attn);
164	    cb(attn, "attn_pre_solve", il);
165	
166	    ggml_tensor * lin_solve = ggml_solve_tri(ctx0, lhs, attn, true, true, false);
167	    attn = ggml_add(ctx0, lin_solve, identity);
168	    cb(attn, "dnet_add_ch_attn_solved", il); // [CS, CS, n_chunks, H_k * n_seqs]
169	
170	    // [S_v, CS, n_chunks, H_v * n_seqs]
171	    v = ggml_mul_mat(ctx0, ggml_cont(ctx0, ggml_transpose(ctx0, v_b)), attn);
172

