106	llama_memory_context_ptr llama_kv_cache_dsa::init_batch(
107	            llama_batch_allocr & balloc,
108	            uint32_t n_ubatch,
109	            bool embd_all) {
110	    GGML_UNUSED(embd_all);
111	
112	    do {
113	        balloc.split_reset();
114	
115	        std::vector<llama_ubatch> ubatches;
116	        while (true) {
117	            auto ubatch = n_stream == 1 ? balloc.split_simple(n_ubatch) : balloc.split_equal(n_ubatch, true, 0);
118	
119	            if (ubatch.n_tokens == 0) {
120	                break;
121	            }
122	
123	            ubatches.push_back(std::move(ubatch)); // NOLINT
124	        }
125	
126	        if (balloc.get_n_used() < balloc.get_n_tokens()) {
127	            // failed to find a suitable split
128	            break;
129	        }
130	
131	        auto sinfos_mla = kv_mla->prepare(ubatches);
132	        if (sinfos_mla.empty()) {
133	            break;
134	        }
135	
136	        auto sinfos_lid = kv_lid->prepare(ubatches);
137	        if (sinfos_lid.empty()) {
138	            break;
139	        }
140	
141	        assert(sinfos_mla.size() == sinfos_lid.size());
142	
143	        return std::make_unique<llama_kv_cache_dsa_context>(
144	                this, std::move(sinfos_mla), std::move(sinfos_lid), std::move(ubatches));
145	    } while (false);
146	
147	    return std::make_unique<llama_kv_cache_dsa_context>(LLAMA_MEMORY_STATUS_FAILED_PREPARE);
148	}
