184	std::string common_arg::to_string() const {
185	    // params for printing to console
186	    const static int n_leading_spaces = 40;
187	    const static int n_char_per_line_help = 70; // TODO: detect this based on current console
188	    std::string leading_spaces(n_leading_spaces, ' ');
189	
190	    std::ostringstream ss;
191	    auto all_args = get_args(); // also contains args_neg
192	    for (const auto & arg : all_args) {
193	        if (arg == all_args.front()) {
194	            if (all_args.size() == 1) {
195	                ss << arg;
196	            } else {
197	                // first arg is usually abbreviation, we need padding to make it more beautiful
198	                auto tmp = std::string(arg) + ", ";
199	                auto spaces = std::string(std::max(0, 7 - (int)tmp.size()), ' ');
200	                ss << tmp << spaces;
201	            }
202	        } else {
203	            ss << arg << (arg != all_args.back() ? ", " : "");
204	        }
205	    }
206	    if (value_hint) ss << " " << value_hint;
207	    if (value_hint_2) ss << " " << value_hint_2;
208	    if (ss.tellp() > n_leading_spaces - 3) {
209	        // current line is too long, add new line
210	        ss << "\n" << leading_spaces;
211	    } else {
212	        // padding between arg and help, same line
213	        ss << std::string(leading_spaces.size() - ss.tellp(), ' ');
214	    }
215	    const auto help_lines = break_str_into_lines(help, n_char_per_line_help);
216	    for (const auto & line : help_lines) {
217	        ss << (&line == &help_lines.front() ? "" : leading_spaces) << line << "\n";
218	    }
219	    return ss.str();
220	}
