253	    ggml_backend_load_all();
254	
255	    std::map<std::string, ggml_backend_buffer_type_t> buft_list;
256	    for (size_t i = 0; i < ggml_backend_dev_count(); ++i) {
257	        auto * dev = ggml_backend_dev_get(i);
258	        auto * buft = ggml_backend_dev_buffer_type(dev);
259	        if (buft) {
260	            buft_list[ggml_backend_buft_name(buft)] = buft;
261	        }
262	    }
263	
264	    for (const auto & override : string_split<std::string>(value, ',')) {
265	        std::string::size_type pos = override.find('=');
266	        if (pos == std::string::npos) {
267	            throw std::invalid_argument("invalid value");
268	        }
269	        std::string tensor_name = override.substr(0, pos);
270	        std::string buffer_type = override.substr(pos + 1);
271	
272	        if (buft_list.find(buffer_type) == buft_list.end()) {
273	            printf("Available buffer types:\n");
274	            for (const auto & it : buft_list) {
275	                printf("  %s\n", ggml_backend_buft_name(it.second));
276	            }
277	            throw std::invalid_argument("unknown buffer type");
278	        }
279	        // keep strings alive and avoid leaking memory by storing them in a static vector
280	        static std::list<std::string> buft_overrides;
281	        buft_overrides.push_back(tensor_name);
282	        overrides.push_back({buft_overrides.back().c_str(), buft_list.at(buffer_type)});
