423	static std::vector<common_download_task> build_url_tasks(const common_params_model & model, common_download_opts opts) {
424	    auto parts = common_download_get_all_parts(model.url);
425	    std::vector<common_download_task> tasks;
426	
427	    // single-part: download straight to model.path if the user gave one (-m), else the cache default
428	    if (parts.size() == 1) {
429	        common_download_task task;
430	        task.url        = parts[0];
431	        task.local_path = model.path.empty() ? get_default_local_path(parts[0]) : model.path;
432	        task.opts       = opts;
433	        tasks.push_back(std::move(task));
434	        return tasks;
435	    }
436	
437	    // multi-part: place each part under the user's -m directory (if given), else the cache default
438	    std::string base_dir;
439	    if (!model.path.empty()) {
440	        auto pos = model.path.rfind('/');
441	        base_dir = pos == std::string::npos ? std::string(".") : model.path.substr(0, pos);
442	    }
443	
444	    for (const auto & part : parts) {
445	        common_download_task task;
446	        task.url  = part;
447	        task.opts = opts;
448	
449	        std::string local = get_default_local_path(part);
450	        if (!base_dir.empty()) {
451	            auto pos = local.rfind('/');
452	            std::string name = pos == std::string::npos ? local : local.substr(pos + 1);
453	            local = base_dir + "/" + name;
454	        }
455	        task.local_path = local;
456	        tasks.push_back(std::move(task));
457	    }
458	    return tasks;
459	}
