106	    for (int sleep_s = 2; total_wait < cool.max_wait; sleep_s = std::min(sleep_s * 2, 32)) {
107	        const int this_wait = std::min(sleep_s, cool.max_wait - total_wait);
108	
109	        fprintf(stderr, "# COOL sleeping %ds (%ds/%ds) %s\n", this_wait, total_wait + this_wait, cool.max_wait,
110	                cell_label);
111	        std::this_thread::sleep_for(std::chrono::seconds(this_wait));
112	        total_wait += this_wait;
113	
114	        const double a = measure_one(backend, cell, reps, set_cand, clear_cand, baseline_cand);
115	        if (a <= 0.0) {
116	            continue;
117	        }
118	
119	        // a faster anchor means the machine got cooler than anything seen so far: adopt it
120	        if (a < anchor_ref) {
121	            anchor_ref = a;
122	        }
123	
124	        if (a <= anchor_ref * (1.0 + cool.eps)) {
125	            fprintf(stderr, "# COOL steady after %ds %s\n", total_wait, cell_label);
126	            return a;
127	        }
128	    }
129	
130	    fprintf(stderr, "# COOL gave up after %ds %s\n", total_wait, cell_label);
131	
132	    return -1.0;
133	}
