135	cell_result measure_cell(ggml_backend_t             backend,
136	                         const perf_cell &          cell,
137	                         int                        reps,
138	                         const std::vector<int> &   order,
139	                         const set_candidate_fn &   set_cand,
140	                         const clear_candidate_fn & clear_cand,
141	                         int                        baseline_cand,
142	                         const cooldown_opts &      cool,
143	                         const char *               cell_label) {
144	    cell_result res;
145	    res.t.assign(order.size(), 0.0);
146	
147	    double anchor_ref = 0.0;
148	
149	    // anchors accepted as clean, as (value, position in order[]). the dirty window starts
150	    // at the position of the last anchor still within eps of anchor_ref, so a downward
151	    // drift (anchor_ref dropping) naturally widens the window to the whole cell.
152	    std::vector<std::pair<double, size_t>> anchors;
153	
154	    auto window_start = [&]() -> size_t {
155	        for (size_t i = anchors.size(); i-- > 0;) {
156	            if (anchors[i].first <= anchor_ref * (1.0 + cool.eps)) {
157	                return anchors[i].second;
158	            }
159	        }
160	        return 0;  // no clean anchor left -> the whole cell is suspect
161	    };
162	
163	    int retries_left = cool.max_retry;
164	
165	    for (size_t i = 0; i < order.size(); ++i) {
166	        res.t[order[i]] = measure_one(backend, cell, reps, set_cand, clear_cand, order[i]);
167	
168	        if (i % 4 != 0) {
169	            continue;
170	        }
171	
172	        const double a = measure_one(backend, cell, reps, set_cand, clear_cand, baseline_cand);
173	        if (a <= 0.0) {
174	            continue;
175	        }
176	
177	        res.anchor_min = res.anchor_min > 0.0 ? std::min(res.anchor_min, a) : a;
178	        res.anchor_max = std::max(res.anchor_max, a);
179	
180	        if (anchor_ref == 0.0) {
181	            anchor_ref = a;
182	            anchors.push_back({ a, i });
183	            continue;
184	        }
185	
186	        const double drift = std::fabs(a - anchor_ref) / anchor_ref;
187	
188	        // a cooler anchor than any so far becomes the reference: whatever was measured
189	        // before it was measured on a hotter machine
190	        if (a < anchor_ref) {
191	            anchor_ref = a;
192	        }
193	
194	        if (drift <= cool.drift) {
195	            anchors.push_back({ a, i });
196	            continue;
197	        }
198	
199	        fprintf(stderr, "# WARN throttling? anchor drift %.1f%% %s\n", 100.0 * drift, cell_label);
200	
201	        if (!cool.enabled) {
202	            anchors.push_back({ a, i });
203	            continue;
204	        }
205	
206	        if (retries_left <= 0) {
207	            fprintf(stderr, "# DIRTY retries exhausted %s\n", cell_label);
208	            res.trusted = false;
209	            return res;
210	        }
211	
212	        const size_t dirty_from = window_start();
213	
214	        const double a_cool =
215	            cool_until_steady(backend, cell, reps, set_cand, clear_cand, baseline_cand, anchor_ref, cool, cell_label);
216	        if (a_cool <= 0.0) {
217	            res.trusted = false;
218	            return res;
219	        }
220	
221	        // the converged anchor is the only clean one now; re-measure the dirty window from it
222	        anchors.clear();
223	        anchors.push_back({ a_cool, dirty_from });
224	
225	        retries_left--;
226	
227	        fprintf(stderr, "# REDO candidates %zu..%zu %s\n", dirty_from, i, cell_label);
228	        for (size_t j = dirty_from; j <= i; ++j) {
229	            res.t[order[j]] = measure_one(backend, cell, reps, set_cand, clear_cand, order[j]);
230	        }
231	    }
232	
233	    return res;
234	}
