 49	// x: [T, IC], w: [K, OC/groups, IC] -> [T * stride, OC]
 50	// the K - stride overlap tail belongs to the next call: added to its head when streaming, else dropped
 51	ggml_tensor * clip_graph_pockettts_seanet::conv_transpose1d(ggml_tensor * x, ggml_tensor * w, ggml_tensor * b, int stride,
 52	                                                            const std::string & state_name) const {
 53	    const int64_t K         = w->ne[0];
 54	    const int64_t T         = x->ne[0];
 55	    const int64_t p_total   = K - stride;
 56	    const bool    depthwise = w->ne[1] == 1 && w->ne[2] > 1;
 57	    const int64_t OC        = depthwise ? w->ne[2] : w->ne[1];
 58	    const int64_t emit_len  = T * stride;
 59	
 60	    // one column per input step, holding the [K, OC] window that col2im scatter-adds at t * stride
 61	    ggml_tensor * col;
 62	    if (depthwise) {
 63	        // one group per channel: a batched matmul over the channels scales the kernel by each step
 64	        ggml_tensor * krn = ggml_reshape_3d(ctx0, w, 1, K, OC);             // [1, K, OC]
 65	        ggml_tensor * xs  = ggml_reshape_3d(ctx0, x, 1, T, OC);             // [1, T, OC]
 66	        col = ggml_mul_mat(ctx0, krn, xs);                                  // [K, T, OC]
 67	        col = ggml_cont(ctx0, ggml_permute(ctx0, col, 0, 2, 1, 3));         // [K, OC, T]
 68	        col = ggml_reshape_2d(ctx0, col, K * OC, T);
 69	    } else {
 70	        ggml_tensor * w2 = ggml_reshape_2d(ctx0, w, K * OC, w->ne[2]);
 71	        w2               = ggml_cont(ctx0, ggml_transpose(ctx0, w2));       // [IC, K * OC]
 72	        ggml_tensor * xt = ggml_cont(ctx0, ggml_transpose(ctx0, x));        // [IC, T]
 73	        col = ggml_mul_mat(ctx0, w2, xt);
 74	    }
 75	    ggml_tensor * full = ggml_col2im_1d(ctx0, col, stride, OC, 0);          // [emit_len + p_total, OC]
 76	
 77	    ggml_tensor * out;
 78	    if (state_name.empty() || p_total == 0) {
 79	        out = ggml_cont(ctx0, ggml_view_2d(ctx0, full, emit_len, full->ne[1], full->nb[1], 0));
 80	    } else {
 81	        // overlap-add the tail the previous call held back
 82	        ggml_tensor * prev = state_in.at(state_name); // [p_total, OC]
 83	        ggml_tensor * head = ggml_add(ctx0, ggml_view_2d(ctx0, full, p_total, full->ne[1], full->nb[1], 0), prev);
 84	        if (emit_len > p_total) {
 85	            ggml_tensor * rest = ggml_view_2d(ctx0, full, emit_len - p_total, full->ne[1], full->nb[1],
 86	                                              (size_t) p_total * full->nb[0]);
 87	            out = ggml_concat(ctx0, head, rest, 0);
 88	        } else {
 89	            out = head;
 90	        }
 91	        state_out.push_back({state_name,
 92	            ggml_cont(ctx0, ggml_view_2d(ctx0, full, p_total, full->ne[1], full->nb[1],
 93	                                         (size_t) emit_len * full->nb[0]))});
 94	    }
 95	
 96	    if (b) {
 97	        out = ggml_add(ctx0, out, ggml_reshape_2d(ctx0, b, 1, b->ne[0]));
 98	    }
 99	    return out;
100	}
