102	ggml_tensor * clip_graph_pockettts_seanet::res_unit(ggml_tensor * x, const clip_seanet::stage & stage, int dilation,
103	                                                    const std::string & state_prefix) const {
104	    ggml_tensor * h = ggml_elu(ctx0, x);
105	    h = conv1d(h, stage.res_conv1_w, stage.res_conv1_b, 1, dilation, false, state_prefix);
106	    h = ggml_elu(ctx0, h);
107	    // the second conv is pointwise, it needs no left context
108	    h = conv1d(h, stage.res_conv2_w, stage.res_conv2_b, 1, 1);
109	    return ggml_add(ctx0, x, h);
110	}
