112	ggml_tensor * clip_graph_pockettts_seanet::encode(ggml_tensor * x) const {
113	    const auto & seanet = model.seanet;
114	
115	    ggml_tensor * cur = conv1d(x, seanet.conv_in_w, seanet.conv_in_b, 1, 1);
116	    cb(cur, "seanet_enc_in", -1);
117	
118	    for (int i = 0; i < hparams.seanet_n_stage; i++) {
119	        const auto & stage  = seanet.stages[i];
120	        const int    stride = hparams.seanet_ratios[i];
121	
122	        cur = res_unit(cur, stage, 1);
123	        cur = ggml_elu(ctx0, cur);
124	        cur = conv1d(cur, stage.scale_conv_w, stage.scale_conv_b, stride, 1);
125	        cb(cur, "seanet_enc_stage", i);
126	    }
127	
128	    cur = ggml_elu(ctx0, cur);
129	    cur = conv1d(cur, seanet.conv_out_w, seanet.conv_out_b, 1, 1);
130	    cb(cur, "seanet_enc_out", -1);
131	
132	    return cur;
133	}
