135	ggml_tensor * clip_graph_pockettts_seanet::decode(ggml_tensor * x) const {
136	    const auto & seanet = model.seanet;
137	    const bool   stream = !state_in.empty();
138	
139	    ggml_tensor * cur = conv1d(x, seanet.conv_in_w, seanet.conv_in_b, 1, 1, false,
140	                               stream ? "dec_in" : "");
141	    cb(cur, "seanet_dec_in", -1);
142	
143	    for (int i = 0; i < hparams.seanet_n_stage; i++) {
144	        const auto & stage = seanet.stages[i];
145	        // the decoder mirrors the encoder, so the ratios are walked backwards
146	        const int    stride = hparams.seanet_ratios[hparams.seanet_n_stage - 1 - i];
147	        const std::string id = std::to_string(i);
148	
149	        cur = ggml_elu(ctx0, cur);
150	        cur = conv_transpose1d(cur, stage.scale_conv_w, stage.scale_conv_b, stride,
151	                               stream ? "dec_up_" + id : "");
152	        cur = res_unit(cur, stage, 1, stream ? "dec_res_" + id : "");
153	        cb(cur, "seanet_dec_stage", i);
154	    }
155	
156	    cur = ggml_elu(ctx0, cur);
157	    cur = conv1d(cur, seanet.conv_out_w, seanet.conv_out_b, 1, 1, false,
158	                 stream ? "dec_out" : "");
159	    cb(cur, "seanet_dec_out", -1);
160	
161	    return cur;
162	}
