225	                                  int *           dst,
226	                                  const int       ncols,
227	                                  const int       nrows,
228	                                  ggml_sort_order order,
229	                                  cudaStream_t    stream) {
230	    // bitonic sort requires ncols to be power of 2
231	    const int ncols_pad = next_power_of_2(ncols);
232	
233	    const dim3 block_dims(ncols_pad, 1, 1);
234	    const dim3 block_nums(nrows, 1, 1);
235	    const size_t shared_mem = ncols_pad * sizeof(int);
