240	    if (order == GGML_SORT_ORDER_ASC) {
241	        k_argsort_f32_i32<GGML_SORT_ORDER_ASC>
242	            <<<block_nums, block_dims, shared_mem, stream>>>(x, dst, ncols, ncols_pad);
243	    } else if (order == GGML_SORT_ORDER_DESC) {
244	        k_argsort_f32_i32<GGML_SORT_ORDER_DESC>
245	            <<<block_nums, block_dims, shared_mem, stream>>>(x, dst, ncols, ncols_pad);
