251	void ggml_cuda_op_argsort(ggml_backend_cuda_context & ctx, ggml_tensor * dst) {
252	    const ggml_tensor * src0 = dst->src[0];
253	    const float * src0_d = (const float *)src0->data;
254	    float * dst_d = (float *)dst->data;
255	    cudaStream_t stream = ctx.stream();
256	
257	    GGML_ASSERT(src0->type == GGML_TYPE_F32);
258	    GGML_ASSERT( dst->type == GGML_TYPE_I32);
259	    GGML_ASSERT(ggml_is_contiguous(src0));
260	
261	    const int64_t ncols = src0->ne[0];
262	    const int64_t nrows = ggml_nrows(src0);
263	
264	    enum ggml_sort_order order = (enum ggml_sort_order) dst->op_params[0];
265	
266	#ifdef GGML_CUDA_USE_CUB
267	    const int    ncols_pad      = next_power_of_2(ncols);
268	    const size_t shared_mem     = ncols_pad * sizeof(int);
269	    const size_t max_shared_mem = ggml_cuda_info().devices[ggml_cuda_get_device()].smpb;
270	
271	    // early return if we can use bitonic argsort
272	    if (shared_mem <= max_shared_mem && ncols <= 1024) {
273	        argsort_f32_i32_cuda_bitonic(src0_d, (int *) dst_d, ncols, nrows, order, stream);
274	        return;
275	    }
276	
277	    const int chunk_nrows = argsort_f32_i32_cuda_cub_chunk_nrows(src0->nb[1], nrows);
278	
279	    ggml_cuda_pool & pool = ctx.pool();
280	
281	    for (int64_t i = 0; i < nrows; i += chunk_nrows) {
282	        int iter_nrows = std::min((int64_t) chunk_nrows, nrows - i);
283	
284	        argsort_f32_i32_cuda_cub(pool, src0_d, (int *) dst_d, ncols, iter_nrows, order, stream);
285	
286	        src0_d += ncols * iter_nrows;
287	        dst_d  += ncols * iter_nrows;
288	    }
289	#else
290	    argsort_f32_i32_cuda_bitonic(src0_d, (int *) dst_d, ncols, nrows, order, stream);
291	#endif
292	}
