 90	    const char4    val1_8 = make_char4(
 91	        table[q1_8[0]], table[q1_8[1]], table[q1_8[2]], table[q1_8[3]]);
 92	
 93	    return make_int2(*((const int *) &val0_8), *((const int *) &val1_8));
