 97	static __device__ __forceinline__ uint32_t unpack_ksigns(const uint8_t v) {
 98	    // v is a 7 bit int, with the 8th sign being encodable as popcnt
 99	    // with xor we can "correct" the bit instead of having to mask
100	    const uint32_t p = __popc(v) & 1;
101	    const uint32_t s = v ^ p << 7;
102	    // broadcast over uint to allow for 0x08040201 / 0x80402010 as selectors
103	    return s * 0x01010101;
