372	static __device__ __forceinline__ float vec_dot_q2_K_q8_1_impl_mmvq(
373	    const int & v, const int * __restrict__ u, const uint8_t * __restrict__ scales,
374	    const half2 & dm2, const float * __restrict__ d8) {
375	
376	    float sumf_d = 0.0f;
377	    float sumf_m = 0.0f;
378	
379	#pragma unroll
380	    for (int i = 0; i < QR2_K; ++i) {
381	        const int sc = scales[2*i];
382	
383	        const int vi = (v >> (2*i)) & 0x03030303;
384	
385	        sumf_d += d8[i] * (ggml_cuda_dp4a(vi, u[i], 0) * (sc & 0xF)); // SIMD dot product
386	
387	        // fill int with 4x m
388	        int m = sc >> 4;
389	        m |= m <<  8;
390	        m |= m << 16;
391	        sumf_m += d8[i] * ggml_cuda_dp4a(m, u[i], 0); // multiply constant q2_K part with sum of q8_1 values
392	    }
393	
394	    const float2 dm2f = __half22float2(dm2);
395	
396	    return dm2f.x*sumf_d - dm2f.y*sumf_m;
397	}
