401	static __device__ __forceinline__ float vec_dot_q2_K_q8_1_impl_mmq(
402	    const int * __restrict__ v, const int * __restrict__ u, const half2 * dm2, const float & d8, const half2 * s8) {
403	
404	    float sumf    = 0.0f;
405	    float sumf_d8 = 0.0f;
406	
407	#pragma unroll
408	    for (int i0 = 0; i0 < QR2_K*VDR_Q2_K_Q8_1_MMQ; i0 += QI8_1) {
409	        const float2 dm2f0 = __half22float2(dm2[i0/(QI8_1/2) + 0]);
410	        int sumi_d0 = 0;
411	
412	        const float2 dm2f1 = __half22float2(dm2[i0/(QI8_1/2) + 1]);
413	        int sumi_d1 = 0;
414	
415	#pragma unroll
416	        for (int i = i0; i < i0 + QI8_1/2; ++i) {
417	            sumi_d0 = ggml_cuda_dp4a(v[i], u[i], sumi_d0);
418	        }
419	        sumf_d8 += dm2f0.x * sumi_d0;
420	
421	#pragma unroll
422	        for (int i = i0 + QI8_1/2; i < i0 + QI8_1; ++i) {
423	            sumi_d1 = ggml_cuda_dp4a(v[i], u[i], sumi_d1);
424	        }
425	        sumf_d8 += dm2f1.x * sumi_d1;
426	
427	        if (i0/QI8_1 < ns8) {
428	            const float2 s8f = __half22float2(s8[i0/QI8_1]);
429	            sumf -= dm2f0.y*s8f.x;
430	            sumf -= dm2f1.y*s8f.y;
431	        } else {
432	            int sumi_m0 = 0;
433	#pragma unroll
434	            for (int i = i0; i < i0 + QI8_1/2; ++i) {
435	                sumi_m0 = ggml_cuda_dp4a(0x01010101, u[i], sumi_m0);
436	            }
437	            sumf_d8 -= dm2f0.y * sumi_m0;
438	
439	            int sumi_m1 = 0;
440	#pragma unroll
441	            for (int i = i0 + QI8_1/2; i < i0 + QI8_1; ++i) {
442	                sumi_m1 = ggml_cuda_dp4a(0x01010101, u[i], sumi_m1);
443	            }
444	            sumf_d8 -= dm2f1.y * sumi_m1;
