465	        const int isc_low = isc % (QK_K/32);
466	        const int sc_shift_low = 4 * (isc / (QK_K/32));
467	        const int sc_low  = (scales[isc_low] >> sc_shift_low) & 0xF;
468	
469	        const int isc_high = isc % (QK_K/64);
470	        const int sc_shift_high = 2 * (isc / (QK_K/64));
471	        const int sc_high = ((scales[(QK_K/32) + isc_high] >> sc_shift_high) & 3) << 4;
472	
473	        const int sc = (sc_low | sc_high) - 32;
474	
475	        const int vil = (vl >> (2*i)) & 0x03030303;
476	
477	        const int vih = ((vh >> i) << 2) & 0x04040404;
478	
479	        const int vi = __vsubss4(vil, vih);
480	
481	        sumf += d8[i] * (ggml_cuda_dp4a(vi, u[i], 0) * sc); // SIMD dot product
482	    }
