349	// Instead of a sequential scan, SSD reformulates the output as:
350	//   Y = (L (.) (C @ B^T)) @ (X * dt)  +  decay * C @ s_init
351	// where L is a causal decay mask derived from A and dt.
352	//
353	// This converts the O(T*N) sequential scan into parallel matmuls.
354	// ============================================================================
355	// Softplus(dt) and inclusive prefix sum per head using CUB BlockScan.
356	// Grid: (n_head, n_seqs)
357	template <int BLOCK_SIZE, int MAX_ITEMS>
358	__global__ void ssm_ssd_prepare_dt_kernel(
359	        const float * __restrict__ dt_raw,
360	        float * __restrict__ dt_sp_out,
361	        float * __restrict__ cs_out,
362	        const int n_head, const int n_tok,
363	        const int dt_stride_tok,   // elements between tokens in dt
364	        const int dt_stride_seq) { // elements between sequences in dt
365	
366	    const int h = blockIdx.x;
367	    const int s = blockIdx.y;
368	
369	    const float * dt_seq = dt_raw + s * dt_stride_seq;
370	
371	    float * dt_sp_seq = dt_sp_out + s * n_tok * n_head;
372	    float * cs_seq    = cs_out    + s * n_tok * n_head;
373	
374	    const int items_per_thread = (n_tok + BLOCK_SIZE - 1) / BLOCK_SIZE;
375	
376	    // Phase 1: softplus with interleaved distribution (t = i*BLOCK_SIZE + threadIdx.x).
377	    // Each warp reads BLOCK_SIZE consecutive tokens, giving coalesced dt_raw loads
378	    // (stride n_head between threads vs. items_per_thread*n_head in blocked layout).
379	    float local_vals[MAX_ITEMS];
380	    for (int i = 0; i < items_per_thread; i++) {
381	        const int t = i * BLOCK_SIZE + threadIdx.x;
382	        if (t < n_tok) {
383	            float val = dt_seq[h + t * dt_stride_tok];
384	            float sp = (val <= 20.0f) ? log1pf(expf(val)) : val;
385	            local_vals[i] = sp;
386	            dt_sp_seq[t * n_head + h] = sp;
387	        } else {
388	            local_vals[i] = 0.0f;
389	        }
390	    }
391	
392	    // Phase 2+3: per-step inclusive scan to build cs[] in token order.
393	    // With interleaved distribution the per-thread total scan would not give token-order
394	    // prefix sums, so we scan one BLOCK_SIZE slab at a time and carry a running total.
